def esc(s): return html.escape(s, quote=True)
def title_from(path):
 p=ROOT/path
 if not p.exists(): return None
 s=p.read_text(errors='ignore')
 m=re.search(r'<h1[^>]*>(.*?)</h1>',s,re.S|re.I) or re.search(r'<title>(.*?)</title>',s,re.S|re.I)
 return re.sub(r'<[^>]+>',' ',html.unescape(m.group(1))).strip() if m else str(path)

def header(active=''):
 links=[('/', 'Home'),('/life.html','Kavomaz Life'),('/kids.html','Kids'),('/book-finder.html','Find a Book'),('/topics/index.html','Topics'),('/resources/index.html','Resources'),('/about.html','About'),('/contact.html','Contact')]
 nav=''.join('<a href="%s"%s>%s</a>'%(u,' class="active" aria-current="page"' if label==active else '',label) for u,label in links)
 return '<a class="skip-link" href="#main-content">Skip to main content</a><header class="site-header"><a class="brand" href="/" aria-label="Kavomaz Books homepage"><img src="/images/kavomaz-books-logo.png" alt="Kavomaz Books logo" width="56" height="56"><span><strong>Kavomaz Books</strong><small>Books for tired minds and growing hearts</small></span></a><button class="menu-toggle" aria-expanded="false" aria-label="Open menu">Menu</button><nav class="nav" aria-label="Main navigation">'+nav+'</nav></header>'

