def page(title,desc,canonical,body,active=''):
 data={'@context':'https://schema.org','@graph':[{'@type':'Organization','@id':SITE+'/#organization','name':'Kavomaz Books','url':SITE+'/','email':'info@kavomaz.com'},{'@type':'WebSite','@id':SITE+'/#website','name':'Kavomaz Books','url':SITE+'/','publisher':{'@id':SITE+'/#organization'}},{'@type':'WebPage','@id':canonical+'#webpage','url':canonical,'name':title,'description':desc,'isPartOf':{'@id':SITE+'/#website'},'inLanguage':'en-US'}]}
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><meta name="description" content="'+esc(desc)+'"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="author" content="Kavomaz Books"><link rel="canonical" href="'+canonical+'"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(desc)+'"><meta property="og:type" content="website"><meta property="og:url" content="'+canonical+'"><meta property="og:image" content="'+SITE+'/images/kavomaz-books-hero.jpg"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">'+json.dumps(data,ensure_ascii=False,separators=(',',':'))+'</script></head><body>'+header(active)+'<main id="main-content">'+body+'</main>'+footer()+'<script defer src="/script.js"></script><script defer src="/assets/js/v6-staging.js"></script></body></html>'

